import json,pathlib,copy
from assets import wire_assets,normalize_links
ROOT=pathlib.Path(__file__).resolve().parents[1]
TITLES={1:'MODEL · Singularity V2 INT8',2:'ENCODER · Qwen3-VL NVFP4 (RTX 40 dùng giả lập)',3:'VAE · Hình ảnh FP16',4:'VAE · Âm thanh',10:'TĂNG TỐC · Turbo Ref2V',11:'NÂNG CAO · Kitchen attention (đã bỏ qua)',12:'NÂNG CAO · Sparse attention (đã bỏ qua)',20:'NHÁNH A · Ảnh đầu/cuối (không dùng)',26:'NHÁNH B · STORYBOARD + THAM CHIẾU',23:'THỜI LƯỢNG CLIP · Giây',24:'Tự đổi giây → frame 17n+5',25:'KHUNG HÌNH · Tỷ lệ / độ phân giải nháp',30:'SEED · Cố định để so sánh',31:'Sampler · Bản nháp',32:'BẢN NHÁP · 4 bước Turbo',62:'DÙNG THAM CHIẾU · Giữ true',70:'PROMPT VIDEO · Tiếng Anh',105:'BƯỚC · false = Tạo nháp | true = Nâng take',123:'LƯU TAKE · Tự lưu latent + conditioning',124:'CHỌN TAKE · latest hoặc take cụ thể',107:'KÍCH THƯỚC BẢN NÂNG · 0.7 MP mặc định',109:'UPSCALER · true = Model latent 3D',110:'MODEL LATENT UPSCALER 3D',111:'Nội suy latent · Nhánh dự phòng',113:'CHIA THỜI GIAN · Nhẹ bộ nhớ hơn',114:'CHIA Ô REFINE · false; bật khi thiếu VRAM',118:'Sampler refine · er_sde; chia ô dùng euler',119:'REFINE · Lịch sigma giữ chuyển động',120:'NÂNG LATENT + REFINE · Bước 2',133:'LoRA tùy chọn · Licon (tắt)',134:'LoRA người thật · Tắt cho hoạt hình 3D',137:'LoRA tùy chọn · Motion Repair (tắt)',142:'GIỮ MÀU · So với bản nháp',144:'HOÀN THIỆN · Nét nhẹ / chuyển sắc',147:'CLARITY · Nhẹ cho hoạt hình 3D',139:'VIDEO · 24 FPS + âm thanh gốc',43:'LƯU MP4 · Nháp hoặc bản nâng',40:'GIẢI MÃ TILED · Giảm đỉnh VRAM',141:'GIẢI MÃ TILED · Màu bản nháp'}
NOTES={90:('BẮT ĐẦU TẠI ĐÂY','Singularity V2 từ workflow đã cung cấp. Dùng PREPARE.bat để chọn storyboard và sheet rồi tự sinh prompt + dây nối cùng thứ tự. Không cần cắt grid.\nBước false: tạo nháp và lưu take. Xem nháp; đổi bước true rồi chạy để nâng take đã chọn.\nBản cho RTX 4060 Ti tắt sparse / Kitchen attention và LoRA người thật. Đây là lựa chọn tương thích, chưa benchmark GPU.'),91:('ĐỘ PHÂN GIẢI / THỜI LƯỢNG','Nháp 0.2 MP, nâng 0.7 MP ban đầu; tăng sau khi chạy ổn. Chiều rộng/cao bội 32; frame 17n+5 ở 24 FPS. 15 giây → 362 frame. Local dùng tối đa 15 giây/lượt; tập dài chia nhiều lượt.\nEncoder NVFP4 được giải lượng tử khi tính trên RTX 40: không có tăng tốc FP4 phần cứng như RTX 50. Cần RAM/pagefile và dung lượng trống phù hợp; không có bảo đảm 16 GB đủ mọi cấu hình.'),92:('ĐỒNG BỘ ẢNH VỚI PROMPT','Picture 1 luôn là nguyên storyboard. Picture 2 trở đi chỉ là ảnh đang bật trong project.json, được PREPARE.bat đánh số và nối cùng lúc.\nMuốn thêm/bỏ ảnh: sửa assets[].enabled trong project rồi chạy PREPARE lại. Không Ctrl+B ảnh trực tiếp mà giữ prompt cũ. Asset tắt dùng mô tả và storyboard, không giả có character sheet.'),121:('NÂNG CẤP LATENT · BƯỚC 2','Dùng latent + conditioning của take đã lưu; sửa prompt hiện tại không đổi take cũ. Tạo lại bước 1 nếu đổi nhân vật/storyboard/phong cách.\nSigma 0.55, 0.42, 0.3158, 0.1579, 0 giảm mức vẽ lại nhưng không bảo đảm khóa mặt. Chia thời gian 68 frame, overlap 17; nếu thiếu VRAM giảm kích thước trước. Nếu bật chia ô refine thì chuyển sampler refine sang euler.'),129:('CÁCH DÙNG HAI BƯỚC','1. BƯỚC = false → Chạy → xem video nháp; take lưu output/h3_takes.\n2. Chọn take cụ thể nếu có nhiều tác vụ; latest lấy take mới nhất khi chạy.\n3. BƯỚC = true → Chạy → nâng take, không cần encode storyboard lại.\nÂm thanh được giữ từ bước 1; bản vá audio-freeze được bộ cài áp dụng có kiểm tra, không cần Node.js.\nColor Transfer chỉ bước 2; finishing cả hai bước. Đây là nâng latent + refine, không phải FlashVSR.'),146:('CẤU HÌNH HOẠT HÌNH 3D','Giữ kiểu nhân vật, tỷ lệ khuôn mặt và chất liệu 3D từ storyboard / sheet. LoRA r34l1sm đã tắt, trigger đã bỏ. Singularity V2 vẫn có thiên hướng model nền; cần đánh giá trên ảnh thật. Không nhận là cấu hình đẹp nhất hoặc nhanh nhất khi chưa render.'),155:('GIỮ CHI TIẾT THAM CHIẾU','Nhánh B dùng vùng tham chiếu riêng 992×1792; video lấy kích thước từ latent rỗng theo bộ chọn độ phân giải. Vì vậy ảnh sheet không bị co chỉ theo bản nháp 0.2 MP.\nVùng tham chiếu lớn làm tăng token ở cả hai bước. Nếu chậm/OOM, giảm còn 544×960 hoặc dùng ít sheet hơn. Không tự giảm độ phân giải storyboard khi các ô đã quá nhỏ.'),160:('KIỂM TRA TRƯỚC KHI CHẠY','Chạy CHECK.bat sau khi START.bat đã mở server. CHECK chỉ xác minh node/model/ảnh/schema, không thay thế một lần render GPU.\nPrompt do skill xuất dùng <Asset:ID>; PREPARE đổi thành <Picture n> theo ảnh thực. Không dán prompt chưa thay token vào node video.')}

def template():
 w=json.loads((ROOT/'sources/original-workflow.json').read_text());w['nodes']=[n for n in w['nodes'] if n['type'] not in ('PixaromaRunTimer','PixaromaMonitor')]
 n={x['id']:x for x in w['nodes']}
 for i in [11,12,133,134,137]:n[i]['mode']=4
 n[70]['size']=[560,700];n[20]['pos']=[1000,800];n[20]['flags']['collapsed']=True;n[26]['pos']=[1000,900];n[26]['size']=[560,600]
 n[3]['widgets_values']=['minimax_h3_video_vae_fp16.safetensors'];n[32]['widgets_values']=['simple',4,1]
 n[26]['widgets_values']=['',992,1792,124,'match'];n[107]['widgets_values'][3]=0.7;n[113]['widgets_values']=[68,17,0.999]
 n[144]['widgets_values']=[0.2,0.2,0.9,0.99,0.02,1,1];n[147]['widgets_values']=[0.05,0.6,1,1,0,1,1]
 for i in [40,141]:
  n[i]['type']='VAEDecodeTiled';n[i]['properties']={'Node name for S&R':'VAEDecodeTiled'};n[i]['widgets_values']=[512,64,32,8]
 for node in w['nodes']:
  if node['id'] in TITLES:node['title']=TITLES[node['id']]
  node.get('properties',{}).pop('guhaiImageValue',None)
 for i,(title,text) in NOTES.items():n[i]['title']=title;n[i]['widgets_values']=[text]
 groups=['MODEL · KHÔNG CẦN ĐỔI','TĂNG TỐC · CẤU HÌNH TƯƠNG THÍCH','STORYBOARD / PROMPT / THAM CHIẾU','THỜI LƯỢNG / TỶ LỆ / BẢN NHÁP','BƯỚC 2 · NÂNG LATENT + REFINE','BƯỚC 1 → XEM NHÁP → BƯỚC 2']
 for group,title in zip(w['groups'],groups):group['title']=title
 w['extra']['singularity_studio_version']='1.0.0';return w

def build():
 p=json.loads((ROOT/'examples/lan-15s.project.json').read_text());t=template()
 paths=['singularity/CHON_STORYBOARD.png','singularity/CHON_LAN.png']
 w,_=wire_assets(t,p,paths);(ROOT/'workflows/Storyboard-4060Ti-VI.json').write_text(json.dumps(w,ensure_ascii=False,indent=2),encoding='utf-8')
 p['seconds']=5;p['run_id']='KiemTra_5s';p['video_prompt']='Use only SHOT 1 from the top-left panel of <Asset:STORYBOARD>. One continuous full-frame 3D animated shot of Lan from <Asset:CHAR_01> seated by golden rice at sunset. Slow push-in, gentle breeze, small natural smile. No cuts. No speech. No grid, labels, subtitles or sheet layout in the video.'
 w,_=wire_assets(t,p,paths);(ROOT/'workflows/KiemTra-5s-VI.json').write_text(json.dumps(w,ensure_ascii=False,indent=2),encoding='utf-8')
 (ROOT/'workflows/template.json').write_text(json.dumps(t,ensure_ascii=False,indent=2),encoding='utf-8')
if __name__=='__main__':build()
